import math
class Solution:
    def nthUglyNumber(self, n: int, a: int, b: int, c: int) -> int:
        def lcm(x, y):
            return x * y // math.gcd(x, y)
        ab, ac, bc = lcm(a,b), lcm(a,c), lcm(b,c)
        abc = lcm(ab, c)
        lo, hi = 1, 2 * 10**9
        while lo < hi:
            mid = (lo + hi) // 2
            cnt = mid//a + mid//b + mid//c - mid//ab - mid//ac - mid//bc + mid//abc
            if cnt < n:
                lo = mid + 1
            else:
                hi = mid
        return lo

class Solution:
    def smallestStringWithSwaps(self, s: str, pairs):
        n = len(s)
        parent = list(range(n))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        for a, b in pairs:
            pa, pb = find(a), find(b)
            if pa != pb:
                parent[pa] = pb
        from collections import defaultdict
        groups = defaultdict(list)
        for i in range(n):
            groups[find(i)].append(i)
        res = list(s)
        for indices in groups.values():
            chars = sorted(res[i] for i in indices)
            for i, idx in enumerate(sorted(indices)):
                res[idx] = chars[i]
        return ''.join(res)

