class Solution:
    def sortItems(self, n, m, group, beforeItems):
        for i in range(n):
            if group[i] == -1:
                group[i] = m
                m += 1
        group_graph = defaultdict(set)
        group_indeg = defaultdict(int)
        item_graph = defaultdict(set)
        item_indeg = defaultdict(int)
        for i in range(n):
            for prev in beforeItems[i]:
                if group[prev] != group[i]:
                    if i not in group_graph[group[prev]]:
                        group_graph[group[prev]].add(group[i])
                        group_indeg[group[i]] = group_indeg.get(group[i],0)+1
                item_graph[prev].add(i)
                item_indeg[i] = item_indeg.get(i,0)+1
        def topo(nodes, graph, indeg):
            q = deque([x for x in nodes if indeg.get(x,0)==0])
            res = []
            while q:
                x = q.popleft()
                res.append(x)
                for y in graph[x]:
                    indeg[y] -= 1
                    if indeg[y] == 0:
                        q.append(y)
            return res if len(res)==len(nodes) else []
        all_groups = set(range(m))
        group_order = topo(all_groups, group_graph, group_indeg)
        if not group_order:
            return []
        group_items = defaultdict(list)
        for i in range(n):
            group_items[group[i]].append(i)
        res = []
        for g in group_order:
            items = group_items[g]
            order = topo(items, item_graph, item_indeg)
            if len(order) != len(items):
                return []
            res.extend(order)
        return res

