class Skiplist:
    def __init__(self):
        self.head = Node()

    def search(self, target: int) -> bool:
        cur = self.head
        while cur:
            while cur.right and cur.right.val < target:
                cur = cur.right
            if cur.right and cur.right.val == target:
                return True
            cur = cur.down
        return False

    def add(self, num: int) -> None:
        stack = []
        cur = self.head
        while cur:
            while cur.right and cur.right.val < num:
                cur = cur.right
            stack.append(cur)
            cur = cur.down
        insert = True
        down = None
        while insert and stack:
            cur = stack.pop()
            cur.right = Node(num, cur.right, down)
            down = cur.right
            insert = random.random() < 0.5
        if insert:
            self.head = Node(-1, None, self.head)

    def erase(self, num: int) -> bool:
        cur = self.head
        found = False
        while cur:
            while cur.right and cur.right.val < num:
                cur = cur.right
            if cur.right and cur.right.val == num:
                found = True
                cur.right = cur.right.right
            cur = cur.down
        return found

