class Solution:
    def dieSimulator(self, n: int, rollMax) -> int:
        MOD = 10**9 + 7
        # dp[j][k] = ways ending with face j, k consecutive
        dp = [[0]*16 for _ in range(6)]
        for j in range(6):
            dp[j][1] = 1
        for i in range(1, n):
            ndp = [[0]*16 for _ in range(6)]
            for j in range(6):
                for nj in range(6):
                    if nj == j:
                        for k in range(1, rollMax[j]):
                            if dp[j][k]:
                                ndp[j][k+1] = (ndp[j][k+1] + dp[j][k]) % MOD
                    else:
                        total = sum(dp[j]) % MOD
                        ndp[nj][1] = (ndp[nj][1] + total) % MOD
            dp = ndp
        return sum(sum(row) for row in dp) % MOD

