class Solution:
    def treeDiameter(self, edges):
        from collections import defaultdict, deque
        graph = defaultdict(list)
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)
        def bfs(start):
            visited = {start}
            queue = deque([(start, 0)])
            farthest, max_dist = start, 0
            while queue:
                node, dist = queue.popleft()
                if dist > max_dist:
                    max_dist = dist
                    farthest = node
                for nei in graph[node]:
                    if nei not in visited:
                        visited.add(nei)
                        queue.append((nei, dist + 1))
            return farthest, max_dist
        far_node, _ = bfs(0)
        _, diameter = bfs(far_node)
        return diameter

class Solution:
