        def dfs(i, j):
            if i < 0 or i >= m or j < 0 or j >= n:
                return False
            if grid[i][j] == 1:
                return True
            grid[i][j] = 1
            a = dfs(i+1, j)
            b = dfs(i-1, j)
            c = dfs(i, j+1)
            d = dfs(i, j-1)
