                res = max(res, s + dfs(i + 1, cnt))
                for c in word_cnt:
                    cnt[c] += word_cnt[c]
            return res
        return dfs(0, avail)

class Solution:
    def encode(self, num: int) -> str:
        return bin(num + 1)[3:]

class Solution:
    def findSmallestRegion(self, regions, region1, region2):
        parent = {}
        for r in regions:
            for i in range(1, len(r)):
                parent[r[i]] = r[0]
        ancestors = set()
        while region1:
            ancestors.add(region1)
            region1 = parent.get(region1)
        while region2 not in ancestors:
            region2 = parent.get(region2)
        return region2

class Solution:
    def generateSentences(self, synonyms, text):
        from collections import defaultdict
        parent = {}
        def find(x):
            parent.setdefault(x, x)
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]
        def union(x, y):
            parent[find(x)] = find(y)
        for a, b in synonyms:
            union(a, b)
        groups = defaultdict(set)
        for w in parent:
            groups[find(w)].add(w)
        words = text.split()
        res = []
        def dfs(i, cur):
            if i == len(words):
                res.append(' '.join(cur))
                return
            root = find(words[i]) if words[i] in parent else None
            if root:
                for w in sorted(groups[root]):
                    dfs(i + 1, cur + [w])
            else:
                dfs(i + 1, cur + [words[i]])
        dfs(0, [])
        return res

class Solution:
    def numberOfWays(self, numPeople: int) -> int:
        MOD = 10**9 + 7
        n = numPeople
        dp = [0] * (n + 1)
        dp[0] = 1
        for i in range(2, n + 1, 2):
            for j in range(0, i - 1, 2):
                dp[i] = (dp[i] + dp[j] * dp[i-2-j]) % MOD
        return dp[n]
